class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def is_pal(x):
            return x == x[::-1]
        ans = 1
        n, m = len(s), len(t)
        for i in range(n):
            for a in range(i, n):
                A = s[i:a+1]
                for j in range(m):
                    for b in range(j, m):
                        B = t[j:b+1]
                        cur = A + B
                        if is_pal(cur):
                            ans = max(ans, len(cur))
        return ans

