class Solution {
public:
    bool isPal(const string& x) {
        int l = 0, r = x.size() - 1;
        while (l < r) if (x[l++] != x[r--]) return false;
        return true;
    }
    int longestPalindrome(string s, string t) {
        int n = s.size(), m = t.size(), ans = 1;
        for (int i = 0; i < n; i++)
            for (int a = i; a < n; a++)
                for (int j = 0; j < m; j++)
                    for (int b = j; b < m; b++) {
                        string cur = s.substr(i, a - i + 1) + t.substr(j, b - j + 1);
                        if ((int)cur.size() > ans && isPal(cur)) ans = cur.size();
                    }
        return ans;
    }
};

