class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n, m = len(s), len(t)

        def side_best(x, from_start):
            L = len(x)
            pal = [[False] * L for _ in range(L)]
            best = [1] * L
            for i in range(L - 1, -1, -1):
                for j in range(i, L):
                    if x[i] == x[j] and (j - i < 2 or pal[i + 1][j - 1]):
                        pal[i][j] = True
                        ln = j - i + 1
                        if from_start:
                            if ln > best[i]:
                                best[i] = ln
                        else:
                            if ln > best[j]:
                                best[j] = ln
            return best

        suf = side_best(s, True)
        pre = side_best(t, False)
        ans = max(max(suf), max(pre))

        f = [[0] * m for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(m):
                if s[i] == t[j]:
                    f[i][j] = (f[i + 1][j - 1] if i + 1 < n and j - 1 >= 0 else 0) + 1
                    k = f[i][j]
                    cand = 2 * k
                    extra = 0
                    if i + k < n:
                        extra = max(extra, suf[i + k])
                    if j - k >= 0:
                        extra = max(extra, pre[j - k])
                    ans = max(ans, cand + extra)
        return ans

