class Solution {
public:
    vector<int> sideBest(const string& x, bool fromStart) {
        int L = x.size();
        vector<vector<char>> pal(L, vector<char>(L, false));
        vector<int> best(L, 1);
        for (int i = L - 1; i >= 0; i--)
            for (int j = i; j < L; j++)
                if (x[i] == x[j] && (j - i < 2 || pal[i + 1][j - 1])) {
                    pal[i][j] = true;
                    int idx = fromStart ? i : j;
                    best[idx] = max(best[idx], j - i + 1);
                }
        return best;
    }
    int longestPalindrome(string s, string t) {
        int n = s.size(), m = t.size();
        auto suf = sideBest(s, true);
        auto pre = sideBest(t, false);
        int ans = max(*max_element(suf.begin(), suf.end()),
                      *max_element(pre.begin(), pre.end()));
        vector<vector<int>> f(n, vector<int>(m, 0));
        for (int i = n - 1; i >= 0; i--)
            for (int j = 0; j < m; j++) {
                if (s[i] != t[j]) continue;
                f[i][j] = (i + 1 < n && j - 1 >= 0 ? f[i + 1][j - 1] : 0) + 1;
                int k = f[i][j], extra = 0;
                if (i + k < n) extra = max(extra, suf[i + k]);
                if (j - k >= 0) extra = max(extra, pre[j - k]);
                ans = max(ans, 2 * k + extra);
            }
        return ans;
    }
};

