    public int longestPalindrome(String s, String t) {
        int n = s.length(), m = t.length();
        int[] suf = sideBest(s, true), pre = sideBest(t, false);
        int ans = 1;
        for (int v : suf) ans = Math.max(ans, v);
        for (int v : pre) ans = Math.max(ans, v);
        int[][] f = new int[n][m];
