            for (int j = 0; j < m; j++) {
                if (s.charAt(i) != t.charAt(j)) continue;
                f[i][j] = (i + 1 < n && j - 1 >= 0 ? f[i + 1][j - 1] : 0) + 1;
                int k = f[i][j], extra = 0;
                if (i + k < n) extra = Math.max(extra, suf[i + k]);
                if (j - k >= 0) extra = Math.max(extra, pre[j - k]);
                ans = Math.max(ans, 2 * k + extra);
            }
