                    pal[i][j] = true;
                    const idx = fromStart ? i : j;
                    best[idx] = Math.max(best[idx], j - i + 1);
                }
        return best;
    };
    const suf = sideBest(s, true), pre = sideBest(t, false);
    let ans = Math.max(...suf, ...pre);
    const n = s.length, m = t.length;
    const f = Array.from({length: n}, () => new Array(m).fill(0));
